const r = await api.get('/mails');
const mails = r.items;
const refundMails = mails.filter(m => m.subject && m.subject.toLowerCase().includes('refund'));
const custIds = [...new Set(refundMails.map(m => m.customer_id).filter(id => id))];
let goldNames = [];
for (const id of custIds) {
  const cust = await api.get(`/customers/${id}`);
  if (cust.tier && cust.tier.toLowerCase() === 'gold') {
    goldNames.push(cust.name);
  }
}
return {goldNames, count: goldNames.length};

